WITH RecentCustomers AS (SELECT * FROM customers WHERE name IS NULL AND LENGTH(name) >= 5), summary AS (SELECT YEAR(signup_date) AS signup_year, ROUND((100 * SUM(CASE WHEN country = 'TH' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_th, COUNT(*) AS total_count FROM RecentCustomers GROUP BY YEAR(signup_date)) SELECT signup_year, pct_th, total_count FROM summary ORDER BY signup_year DESC, pct_th
